using BigaFund.Models;

namespace BigaFund.Services;

public static class QuantCalculator
{
    private const decimal DefaultRf = 2.0m; // 默认无风险年化利率 2.0%
    private const int TradingDaysPerYear = 250; // A股年交易日标准

    /// <summary>
    /// 计算指定时间区间的量化风控指标
    /// </summary>
    public static QuantMetrics CalculateMetrics(
        IReadOnlyList<NavRecord> navHistory,
        string periodName = "全周期",
        IReadOnlyList<BenchmarkRecord>? benchmarkHistory = null,
        decimal riskFreeRate = DefaultRf)
    {
        var metrics = new QuantMetrics
        {
            PeriodName = periodName
        };

        if (navHistory == null || navHistory.Count < 2)
        {
            return metrics;
        }

        metrics.StartDate = navHistory[0].Date;
        metrics.EndDate = navHistory[^1].Date;
        metrics.TradingDays = navHistory.Count;

        // 优先使用累计净值进行除权后真实收益率计算，若累计净值异常则降级单位净值
        decimal startNav = GetEffectiveNav(navHistory[0]);
        decimal endNav = GetEffectiveNav(navHistory[^1]);

        if (startNav <= 0) startNav = 1.0m;

        // 1. 区间总收益率 (%)
        metrics.TotalReturn = ((endNav - startNav) / startNav) * 100m;

        // 2. 年化复合收益率 CAGR (%)
        double totalReturnRatio = (double)(endNav / startNav);
        if (totalReturnRatio > 0 && metrics.TradingDays > 5)
        {
            double years = (double)metrics.TradingDays / TradingDaysPerYear;
            double cagr = Math.Pow(totalReturnRatio, 1.0 / years) - 1.0;
            metrics.AnnualizedReturn = (decimal)(cagr * 100.0);
        }
        else
        {
            metrics.AnnualizedReturn = metrics.TotalReturn;
        }

        // 3. 计算日收益率序列与下行收益率序列
        var dailyReturns = new List<double>();
        var downsideReturns = new List<double>();
        double targetDailyRf = (double)(riskFreeRate / 100m / TradingDaysPerYear);

        for (int i = 1; i < navHistory.Count; i++)
        {
            decimal prev = GetEffectiveNav(navHistory[i - 1]);
            decimal curr = GetEffectiveNav(navHistory[i]);
            if (prev <= 0) continue;

            double r = (double)((curr - prev) / prev);
            dailyReturns.Add(r);

            double downsideDiff = r - targetDailyRf;
            if (downsideDiff < 0)
            {
                downsideReturns.Add(downsideDiff * downsideDiff);
            }
            else
            {
                downsideReturns.Add(0.0);
            }
        }

        // 4. 年化波动率 (%)
        if (dailyReturns.Count > 1)
        {
            double mean = dailyReturns.Average();
            double sumSquares = dailyReturns.Sum(r => Math.Pow(r - mean, 2));
            double dailyStdDev = Math.Sqrt(sumSquares / (dailyReturns.Count - 1));
            double annVol = dailyStdDev * Math.Sqrt(TradingDaysPerYear);
            metrics.AnnualizedVolatility = (decimal)(annVol * 100.0);
        }

        // 5. 历史最大回撤 (MDD) 及区间定位与修复期计算
        decimal peak = -1m;
        int peakIdx = 0;
        decimal maxDrawdown = 0m;
        int mddPeakIdx = -1;
        int mddTroughIdx = -1;

        for (int i = 0; i < navHistory.Count; i++)
        {
            var record = navHistory[i];
            decimal nav = GetEffectiveNav(record);
            if (nav > peak)
            {
                peak = nav;
                peakIdx = i;
            }
            else if (peak > 0)
            {
                decimal drawdown = (peak - nav) / peak; // 正百分比
                if (drawdown > maxDrawdown)
                {
                    maxDrawdown = drawdown;
                    mddPeakIdx = peakIdx;
                    mddTroughIdx = i;
                }
            }
        }

        metrics.MaxDrawdown = maxDrawdown * 100m;
        if (mddPeakIdx >= 0 && mddTroughIdx >= 0)
        {
            metrics.MaxDrawdownPeakDate = navHistory[mddPeakIdx].Date;
            metrics.MaxDrawdownTroughDate = navHistory[mddTroughIdx].Date;

            // 计算从谷底回升至前高所需的交易日天数
            decimal peakVal = GetEffectiveNav(navHistory[mddPeakIdx]);
            for (int k = mddTroughIdx + 1; k < navHistory.Count; k++)
            {
                if (GetEffectiveNav(navHistory[k]) >= peakVal)
                {
                    metrics.RecoveryTradingDays = k - mddTroughIdx;
                    break;
                }
            }
        }

        // 6. 夏普比率 Sharpe Ratio
        if (metrics.AnnualizedVolatility > 0)
        {
            metrics.SharpeRatio = (metrics.AnnualizedReturn - riskFreeRate) / metrics.AnnualizedVolatility;
        }

        // 7. 卡玛比率 Calmar Ratio
        if (metrics.MaxDrawdown > 0)
        {
            metrics.CalmarRatio = metrics.AnnualizedReturn / metrics.MaxDrawdown;
        }

        // 8. 索提诺比率 Sortino Ratio
        if (downsideReturns.Count > 1)
        {
            double downsideVar = downsideReturns.Sum() / (downsideReturns.Count - 1);
            double downsideStdDev = Math.Sqrt(downsideVar) * Math.Sqrt(TradingDaysPerYear);
            if (downsideStdDev > 0)
            {
                double sortino = (double)(metrics.AnnualizedReturn - riskFreeRate) / (downsideStdDev * 100.0);
                metrics.SortinoRatio = (decimal)sortino;
            }
        }

        // 9. 基准对比与资本资产定价模型 (CAPM: Beta, Alpha, 信息比率)
        if (benchmarkHistory != null && benchmarkHistory.Count > 0)
        {
            var bmInRange = benchmarkHistory.Where(b => b.Date >= metrics.StartDate && b.Date <= metrics.EndDate).OrderBy(b => b.Date).ToList();
            if (bmInRange.Count >= 2)
            {
                metrics.BenchmarkReturn = bmInRange[^1].CumulativeReturnRate - bmInRange[0].CumulativeReturnRate;

                // 构建基准日收益率字典 (按日期匹配)
                var bmDailyRetMap = new Dictionary<DateTime, double>();
                for (int i = 1; i < bmInRange.Count; i++)
                {
                    double prevVal = 100.0 + (double)bmInRange[i - 1].CumulativeReturnRate;
                    double currVal = 100.0 + (double)bmInRange[i].CumulativeReturnRate;
                    if (prevVal > 0)
                    {
                        bmDailyRetMap[bmInRange[i].Date] = (currVal - prevVal) / prevVal;
                    }
                }

                // 对齐基金与基准的日收益率
                var fundAligned = new List<double>();
                var bmAligned = new List<double>();
                for (int i = 1; i < navHistory.Count; i++)
                {
                    var d = navHistory[i].Date;
                    if (bmDailyRetMap.TryGetValue(d, out double bmR))
                    {
                        decimal prev = GetEffectiveNav(navHistory[i - 1]);
                        decimal curr = GetEffectiveNav(navHistory[i]);
                        if (prev > 0)
                        {
                            fundAligned.Add((double)((curr - prev) / prev));
                            bmAligned.Add(bmR);
                        }
                    }
                }

                int n = fundAligned.Count;
                if (n >= 10)
                {
                    double meanFund = fundAligned.Average();
                    double meanBm = bmAligned.Average();

                    double cov = 0;
                    double varBm = 0;
                    var trackingDiffs = new List<double>();

                    for (int i = 0; i < n; i++)
                    {
                        cov += (fundAligned[i] - meanFund) * (bmAligned[i] - meanBm);
                        varBm += Math.Pow(bmAligned[i] - meanBm, 2);
                        trackingDiffs.Add(fundAligned[i] - bmAligned[i]);
                    }

                    cov /= (n - 1);
                    varBm /= (n - 1);

                    double beta = varBm > 1e-12 ? cov / varBm : 1.0;
                    metrics.Beta = Math.Round((decimal)beta, 2);

                    // 基准年化收益率
                    double years = (double)metrics.TradingDays / TradingDaysPerYear;
                    double bmRatio = (100.0 + (double)bmInRange[^1].CumulativeReturnRate) / Math.Max(1.0, 100.0 + (double)bmInRange[0].CumulativeReturnRate);
                    double bmCagr = years > 0 && bmRatio > 0 ? (Math.Pow(bmRatio, 1.0 / years) - 1.0) * 100.0 : (double)metrics.BenchmarkReturn;

                    // CAPM Alpha = 基金年化 - (Rf + Beta * (基准年化 - Rf))
                    double alpha = (double)metrics.AnnualizedReturn - ((double)riskFreeRate + beta * (bmCagr - (double)riskFreeRate));
                    metrics.Alpha = Math.Round((decimal)alpha, 2);

                    // 信息比率 IR = 超额年化收益 / 年化跟踪误差
                    double meanDiff = trackingDiffs.Average();
                    double varDiff = trackingDiffs.Sum(d => Math.Pow(d - meanDiff, 2)) / (n - 1);
                    double te = Math.Sqrt(varDiff) * Math.Sqrt(TradingDaysPerYear); // 年化跟踪误差
                    metrics.TrackingError = Math.Round((decimal)(te * 100.0), 2);
                    if (te > 1e-6)
                    {
                        double ir = (meanDiff * TradingDaysPerYear) / te;
                        metrics.InformationRatio = Math.Round((decimal)ir, 2);
                    }

                    // 特雷诺比率 Treynor = (Rp - Rf) / Beta
                    if (Math.Abs(beta) > 1e-4)
                    {
                        double treynor = ((double)metrics.AnnualizedReturn - (double)riskFreeRate) / beta;
                        metrics.TreynorRatio = Math.Round((decimal)treynor, 2);
                    }

                    // 机构级上行捕获率 (UCR) & 下行捕获率 (DCR)
                    var upPairs = fundAligned.Zip(bmAligned).Where(p => p.Second > 0).ToList();
                    var downPairs = fundAligned.Zip(bmAligned).Where(p => p.Second < 0).ToList();

                    if (upPairs.Count >= 3)
                    {
                        double meanFundUp = upPairs.Select(p => p.First).Average();
                        double meanBmUp = upPairs.Select(p => p.Second).Average();
                        if (Math.Abs(meanBmUp) > 1e-8)
                        {
                            metrics.UpsideCaptureRatio = Math.Round((decimal)((meanFundUp / meanBmUp) * 100.0), 1);
                        }
                    }

                    if (downPairs.Count >= 3)
                    {
                        double meanFundDown = downPairs.Select(p => p.First).Average();
                        double meanBmDown = downPairs.Select(p => p.Second).Average();
                        if (Math.Abs(meanBmDown) > 1e-8)
                        {
                            metrics.DownsideCaptureRatio = Math.Round((decimal)((meanFundDown / meanBmDown) * 100.0), 1);
                        }
                    }

                    if (metrics.DownsideCaptureRatio != 0m)
                    {
                        metrics.CaptureRatio = Math.Round(metrics.UpsideCaptureRatio / metrics.DownsideCaptureRatio, 2);
                    }
                }
            }
        }

        // 10. 极端下行风险与尾部风险度量 (历史模拟法 95% 置信度 VaR & CVaR)
        if (dailyReturns.Count > 0)
        {
            var (var95, cvar95) = CalculateVaRAndCVaR(dailyReturns, 0.95);
            metrics.VaR95 = var95;
            metrics.CVaR95 = cvar95;
        }

        // 11. 历史经典极端市场黑天鹅情景压力测试
        metrics.StressTestScenarios = CalculateStressTestScenarios(navHistory, benchmarkHistory);

        // 12. 滚动时变风控指标 (默认 120 交易日滚动窗口，捕获风格漂移)
        metrics.RollingMetrics = CalculateRollingMetrics(navHistory, window: 120, riskFreeRate: riskFreeRate);

        // 13. 生成全历史回撤水下曲线时序 (Underwater Plot Series) 与当前回撤深度
        metrics.DrawdownSeries = CalculateDrawdownSeries(navHistory);
        metrics.CurrentDrawdown = metrics.DrawdownSeries.Count > 0 ? Math.Abs(metrics.DrawdownSeries[^1].DrawdownRate) : 0m;

        // 14. 机构级非正态分布与下行风险全景体系 (Downside Deviation, Omega, Ulcer Index, Martin, Pain)
        metrics.DownsideDeviation = CalculateDownsideDeviation(dailyReturns, riskFreeRate);
        metrics.OmegaRatio = CalculateOmegaRatio(dailyReturns, riskFreeRate);
        var (ui, martin) = CalculateUlcerIndexAndMartin(navHistory, metrics.AnnualizedReturn, riskFreeRate);
        metrics.UlcerIndex = ui;
        metrics.MartinRatio = martin;
        metrics.PainRatio = CalculatePainRatio(navHistory, metrics.AnnualizedReturn);

        // 15. 历史上前五大最深回撤周期解构 (Top 5 Drawdown Episodes)
        metrics.DrawdownEpisodes = CalculateDrawdownEpisodes(navHistory);

        // 16. Barra CNE5/CNE6 风格多因子暴露与收益归因分解
        metrics.BarraAttribution = CalculateBarraAttribution(navHistory, benchmarkHistory, riskFreeRate);

        // 17. 基金经理职业生涯任期统计与滚动胜率矩阵
        metrics.ManagerProfile = CalculateManagerProfileAndWinRate(navHistory, benchmarkHistory);

        // 18. 机构级非正态极值尾部风险体系 (Cornish-Fisher 展开式与高阶矩风控)
        metrics.TailRisk = CalculateTailRiskMetrics(dailyReturns);

        // 19. 全生命周期水下曲线与套牢时长深度解构
        metrics.UnderwaterAnalysis = CalculateUnderwaterAnalysis(navHistory);

        // 20. Fama-French 五因子资产定价模型 (FF5: MKT, SMB, HML, RMW, CMA)
        metrics.FamaFrenchResult = CalculateFamaFrench5Attribution(navHistory, benchmarkHistory, riskFreeRate);

        // 21. 基金经理择时与选股双模型解构 (Treynor-Mazuy & Henriksson-Merton)
        metrics.TimingAbility = CalculateTimingAndSelectionAbility(navHistory, benchmarkHistory, riskFreeRate);

        // 22. 牛熊双边非对称捕获与极端暴跌条件相关性分析
        metrics.BullBearCapture = CalculateBullBearCapture(navHistory, benchmarkHistory, riskFreeRate);

        // 23. 机构级 FOF 尽调六维雷达综合评分与晨星五星等效评级报告卡
        metrics.DueDiligence = CalculateDueDiligenceCard(metrics, navHistory);

        // 24. 机构级历史极端黑天鹅危机压力测试回放与合成代理推演 (Phase 12)
        metrics.CrisisReplay = ReplayHistoricalCrisisScenarios(navHistory, metrics.Beta, benchmarkHistory);

        // 25. 前瞻性多维宏观情景联合冲击与传导压力测试 (Phase 13)
        metrics.MacroStressResult = EvaluateMacroScenarioStress(metrics.Beta, currentVaR99: metrics.VaR95 * 1.4m);

        // 26. Phase 23 Fama-French 运气剔除与基金经理真技能 Bootstrap 检验
        metrics.LuckVsSkillAudit = EvaluateManagerLuckVsSkillBootstrap(
            dailyReturns.Select(r => (decimal)r).ToList(),
            metrics.Alpha);

        // 27. Phase 24 基金经理跨任期断层检验与换帅冲击预警审计
        metrics.ManagerTransitionAudit = EvaluateManagerTransitionBreakpoint(
            dailyReturns.Select(r => (decimal)r).ToList(),
            metrics.Alpha,
            metrics.Beta,
            metrics.AnnualizedVolatility,
            metrics.MaxDrawdown);

        return metrics;
    }

