    private static readonly StressPreset[] HistoricalCrisisPresets = new[]
    {
        new StressPreset("2015年A股异常波动 (去杠杆/千股跌停)", "杠杆资金清理引发多轮深度踩踏，千股跌停流动性急剧冻结", new DateTime(2015, 6, 12), new DateTime(2015, 8, 26), -42.5m),
        new StressPreset("2016年初A股熔断冲击", "熔断机制引发恐慌性抛售，两周内两度提前休市", new DateTime(2015, 12, 31), new DateTime(2016, 1, 29), -21.0m),
        new StressPreset("2018年单边去杠杆与贸易冲突", "中美经贸争端全面升级叠加国内金融去杠杆，全年单边震荡阴跌", new DateTime(2018, 1, 26), new DateTime(2018, 12, 28), -25.3m),
        new StressPreset("2020年全球黑天鹅流动性挤兑", "全球资本市场剧烈去杠杆，美股数次熔断，原油破负值与恐慌抛售", new DateTime(2020, 1, 20), new DateTime(2020, 3, 23), -12.8m),
        new StressPreset("2021年'茅指数'核心抱团瓦解", "机构高估值抱团资产泡沫出清，白马蓝筹股剧烈下挫回撤", new DateTime(2021, 2, 18), new DateTime(2021, 3, 25), -15.4m),
        new StressPreset("2024年初微盘踩踏与雪球爆仓", "雪球产品集中敲入叠加量化DMA流动性平仓，小微盘遭遇系统性踩踏", new DateTime(2024, 1, 2), new DateTime(2024, 2, 5), -7.3m)
    };

    /// <summary>
    /// 评估基金在 A 股历史典型极端黑天鹅危机区间的压力测试表现
    /// </summary>
    public static List<StressTestScenario> CalculateStressTestScenarios(
        IReadOnlyList<NavRecord> navHistory,
        IReadOnlyList<BenchmarkRecord>? benchmarkHistory = null)
    {
        var list = new List<StressTestScenario>();
        if (navHistory == null || navHistory.Count < 2) return list;

        DateTime fundStart = navHistory[0].Date;
        DateTime fundEnd = navHistory[^1].Date;

        foreach (var preset in HistoricalCrisisPresets)
        {
            if (preset.End < fundStart || preset.Start > fundEnd)
            {
                continue;
            }

            var slice = navHistory
                .Where(n => n.Date >= preset.Start && n.Date <= preset.End)
                .OrderBy(n => n.Date)
                .ToList();

            if (slice.Count < 2)
            {
                continue;
            }

            decimal startNav = GetEffectiveNav(slice[0]);
            decimal endNav = GetEffectiveNav(slice[^1]);
            if (startNav <= 0) continue;

            decimal fundRet = ((endNav - startNav) / startNav) * 100m;

            // 计算该危机区间内的最大回撤
            decimal peak = -1m;
            decimal maxDd = 0m;
            foreach (var r in slice)
            {
                decimal nav = GetEffectiveNav(r);
                if (nav > peak) peak = nav;
                else if (peak > 0)
                {
                    decimal dd = (peak - nav) / peak;
                    if (dd > maxDd) maxDd = dd;
                }
            }

            // 计算同期基准表现
            decimal bmRet = preset.DefaultCsi300Drop;
            if (benchmarkHistory != null && benchmarkHistory.Count > 0)
            {
                var bmSlice = benchmarkHistory
                    .Where(b => b.Date >= preset.Start && b.Date <= preset.End)
                    .OrderBy(b => b.Date)
                    .ToList();
                if (bmSlice.Count >= 2)
                {
                    bmRet = bmSlice[^1].CumulativeReturnRate - bmSlice[0].CumulativeReturnRate;
                }
            }

            decimal excess = fundRet - bmRet;
            string rating = excess switch
            {
                >= 10.0m => "卓越防御",
                >= 3.0m => "跑赢基准",
                >= -3.0m => "跟随基准",
                _ => "高弹性承压"
            };

            if (fundRet >= 0 && bmRet < -5.0m)
            {
                rating = "卓越防御";
            }

            list.Add(new StressTestScenario
            {
                ScenarioName = preset.Name,
                Description = preset.Desc,
                StartDate = slice[0].Date,
                EndDate = slice[^1].Date,
                FundReturnRate = Math.Round(fundRet, 2),
                BenchmarkReturnRate = Math.Round(bmRet, 2),
                MaxDrawdown = Math.Round(maxDd * 100m, 2),
                DefenseRating = rating
            });
        }

        return list;
    }

