            (Code: "SELL_ARRIVE ➔ SWEEP_LOB", Name: "侵略卖单砸盘 ➔ 深度排队踩踏", Mu: 18.2, Alpha: 7.2, Beta: 10.5, Deplete: 74.0),
            (Code: "CANCEL_SPIKE ➔ SPREAD_WIDEN", Name: "高频撤单脉冲 ➔ 价差骤扩失衡", Mu: 9.8, Alpha: 4.2, Beta: 12.0, Deplete: 48.0),
            (Code: "CROSS_ETF ➔ ARB_CASCADE", Name: "宽基成分联动 ➔ 跨品种套利级联", Mu: 12.0, Alpha: 4.8, Beta: 11.5, Deplete: 55.0)
        };

        var items = new List<HawkesExcitationMatrixItem>();
        double sumDeplete = 0;
        double maxBranching = 0;

        foreach (var ch in hawkesChannels)
        {
            double branching = Math.Round(ch.Alpha / ch.Beta, 3);
            if (branching > maxBranching) maxBranching = branching;

            string badge;
