            if (branching >= 0.65 || ch.Deplete >= 70.0)
            {
                badge = "⚡ 临界自激雪崩区";
                advice = $"互激分支比贡献高达 {branching:F3}，LOB 队列瞬时耗尽概率 {ch.Deplete:F1}%。订单流处于临界雪崩边缘，立即撤出单边被动做市挂单，转向隐蔽式 TWAP 拆单保护。";
            }
            else if (ch.Deplete >= 50.0)
            {
                badge = "🌪️ 跨品类级联抽单";
                advice = $"监测到跨品种套利级联激发现象，价差拉宽。采用队列反应式微观动态偏置，捕获知情交易冲击后的均值回复价差。";
