                advice = $"处于单值稳态极小值势井，距离分岔曲面安全距离 {distBif:F3}。动力学耗散平稳，维持基准风险预算配置。";
            }

            items.Add(new ThomCatastropheDynamicItem
            {
                AssetCode = fund.Code,
                AssetName = !string.IsNullOrEmpty(fund.Name) ? fund.Name : fund.Code,
                Weight = comp.Weight,
                MaxLyapunovExponent = (decimal)lyap,
                ThomControlParameterAlpha = (decimal)alpha,
                ThomControlParameterBeta = (decimal)beta,
                BifurcationDiscriminantDelta = (decimal)delta,
                DistanceToBifurcationSurface = (decimal)distBif,
                AntiHysteresisHedgingBufferPct = (decimal)hedgeBuffer,
                CatastropheRegimeBadge = badge,
