        result.CatastropheItems = items;
        result.PortfolioMaxLyapunovExponent = Math.Round((decimal)maxLyap, 3);
        result.LyapunovPredictionHorizonDays = maxLyap > 1e-4 ? Math.Round((decimal)(1.0 / maxLyap), 1) : 20.0m;
