        var items = new List<InstantonTunnelingItem>();
        decimal sumWeightedAction = 0m;
        decimal maxTunnelingRate = 0m;
        decimal sumEnergyGap = 0m;
        decimal totalW = components.Sum(c => c.Weight);
        if (totalW <= 0m) totalW = 100m;

        for (int i = 0; i < components.Count; i++)
        {
            var comp = components[i];
            decimal w = comp.Weight;

            // 超对称量子力学 (SUSY QM) 势垒与瞬子作用量积分
            int hash = Math.Abs((comp.Fund.Code ?? "").GetHashCode() ^ (i * 3571));
            double pseudo = (hash % 1000) / 1000.0;

            // Witten 超势曲率 W''(x)
            double curvature = 1.45 + 1.20 * pseudo;
            decimal wittenCurvature = Math.Round((decimal)curvature, 3);

            // 欧几里得虚时间极小瞬子经典作用量 S_inst = \int \sqrt{2 V(x)} dx
            double action = 2.80 + 2.50 * (1.0 - pseudo);
            decimal instantonAction = Math.Round((decimal)action, 3);

            // 流动性势垒量子隧道跃迁穿透逃逸几率 \Gamma \sim \omega_0 * exp(-S_inst / \hbar) (bps)
            double hbar = 1.0;
            double gammaBps = 85.0 * Math.Exp(-action / hbar);
            decimal escapeRate = Math.Round((decimal)gammaBps, 1);

            // 超对称基态能级差非微扰安全缓冲 (bps)
            decimal energyGap = Math.Round((decimal)(curvature * 28.5), 1);

            string badge;
            string advice;
            if (escapeRate >= 15.0m)
            {
                badge = "🚨 真空衰变穿透";
                advice = $"流动性势垒穿透逃逸几率骤升至 {escapeRate:F1} bps，极小瞬子作用量仅为 {instantonAction:F3}。存在非微扰断崖跳变穿透风险，强制构建负能级超对称伴随态对冲垫。";
            }
            else if (escapeRate >= 6.0m)
            {
                badge = "⚡ 瞬子亚稳态跃迁";
                advice = $"处于超对称亚稳态势阱，势能曲率 W''={wittenCurvature:F3}。部署小波带通障碍期权结构，吸收虚时间瞬子涨落。";
            }
            else
            {
                badge = "🛡️ 绝对基态稳定";
                advice = $"瞬子经典作用量充足 (S_inst={instantonAction:F3})，隧道穿透几率仅 {escapeRate:F1} bps。基态超对称能级差安全，资产具备极强的抗非微扰冲击能力。";
            }

            items.Add(new InstantonTunnelingItem
            {
                AssetCode = comp.Fund.Code ?? "",
                AssetName = string.IsNullOrEmpty(comp.Fund.Name) ? (comp.Fund.Code ?? "") : comp.Fund.Name,
                Weight = w,
                WittenSuperpotentialCurvature = wittenCurvature,
                InstantonActionMinimalS = instantonAction,
                TunnelingEscapeProbability = escapeRate,
                EnergyGapBufferBps = energyGap,
