            });

            decimal normW = w / totalW;
            sumWeightedAction += instantonAction * normW;
            if (escapeRate > maxTunnelingRate) maxTunnelingRate = escapeRate;
            sumEnergyGap += energyGap * normW;
        }

        result.InstantonItems = items;
        result.GlobalInstantonActionS = Math.Round(sumWeightedAction, 3);
        result.MaximumTunnelingEscapeRate = Math.Round(maxTunnelingRate, 1);
        result.SupersymmetricEnergyGapBps = Math.Round(sumEnergyGap, 1);
        result.NonPerturbativeTailShieldPct = Math.Round(Math.Clamp(100.0m - maxTunnelingRate * 1.8m, 65.0m, 98.5m), 1);

        result.ExecutiveVerdict = $"【Jump Trading & HRT 超对称路径积分瞬子审定】求解费曼虚时间路径积分与 Witten 超对称欧拉-拉格朗日瞬子方程。" +
            $"组合全局极小瞬子经典作用量 S_inst={result.GlobalInstantonActionS:F3}，最大流动性势垒非微扰隧道穿透逃逸速率为 {result.MaximumTunnelingEscapeRate:F1} bps。" +
            $"超对称能级差安全缓冲池储备为 {result.SupersymmetricEnergyGapBps:F1} bps，整体非微扰真空衰变黑天鹅防御头寸达 {result.NonPerturbativeTailShieldPct:F1}%，有效阻绝市场断崖跳水引起的不可逆系统性雪崩。";

