                : portVol;
            if (assetVol <= 0.001) assetVol = 0.18;

            int hash = Math.Abs((f.Code ?? "").GetHashCode() ^ (i + 19));

            // 因果不变性纯度评分 (0~100): 典型 68~95
            double invarianceScore = 72.0 + 18.0 * Math.Cos(assetVol * 6.0) + (hash % 100) / 10.0;
            invarianceScore = Math.Clamp(invarianceScore, 65.0, 96.0);

            // 反事实 do-calculus 外生干预纯化 Alpha (bps): 典型 12~32 bps
            double doAlpha = 14.0 + 12.0 * (invarianceScore / 80.0) + (double)(normW * 6m);
            doAlpha = Math.Clamp(doAlpha, 10.0, 35.0);

            // DAG 因果有向拓扑直系父节点数: 1~3
            int directParents = 1 + (hash % 3);

            // 后门混杂因子虚假偏差衰减率 (%): 45%~85%
            double biasAttenuation = 50.0 + 28.0 * Math.Tanh(invarianceScore / 70.0) + (hash % 30) / 5.0;
            biasAttenuation = Math.Clamp(biasAttenuation, 48.0, 88.0);

            // 跨微观与宏观环境因果稳定性比率
            double stabilityRatio = 1.15 + 0.55 * (invarianceScore / 85.0);
            stabilityRatio = Math.Clamp(stabilityRatio, 1.10, 1.85);

            string badge;
            string advice;
