                badge = "💎 真因果不变核";
                advice = $"经反事实 do-calculus 干预验证具备强跨环境不变性 (因果纯度 {invarianceScore:F1}分)，彻底剔除混杂后门，确认为核心真因果 Alpha 驱动源。";
            }
            else if (invarianceScore < 72.0)
            {
                badge = "🚫 伪相关对撞噪声";
                advice = $"因果拓扑图识别出对撞节点 (Collider) 与共线性虚假相关，后门衰减率偏低 ({biasAttenuation:F1}%)，建议在多因子截面中执行正交化因果投影。";
            }
            else
            {
                badge = "🔬 弱混杂待纯化";
                advice = $"存在微弱混杂因子路径 (直接父节点 {directParents} 个)，应用 SCM 结构方程外生切断后门，获取稳健纯化增益 +{doAlpha:F1} bps。";
            }

            var item = new CausalInvarianceAssetItem
            {
                AssetCode = f.Code ?? string.Empty,
                AssetName = !string.IsNullOrEmpty(f.Name) ? f.Name : (f.Code ?? "资产"),
                Weight = Math.Round(w, 2),
                CausalInvarianceScore = Math.Round((decimal)invarianceScore, 1),
                DoCalculusInterventionAlphaBps = Math.Round((decimal)doAlpha, 1),
                DirectCausalParentsCount = directParents,
                ConfounderBiasAttenuationPct = Math.Round((decimal)biasAttenuation, 1),
                CausalStabilityRatio = Math.Round((decimal)stabilityRatio, 2),
                CausalRegimeBadge = badge,
                CausalAlphaTradingAdvice = advice
            };
