            double crossBeta = 0.18 + 0.22 * Math.Sqrt(assetVol) + (hash % 25) / 120.0;
            crossBeta = Math.Clamp(crossBeta, 0.12, 0.45);

            // 分支比率谱半径 ρ_i = (α_ii + ∑ α_ij) / β (设 β=1.0)
            double branchingRadius = (selfAlpha * 0.65 + crossBeta * 0.55);
            branchingRadius = Math.Clamp(branchingRadius, 0.30, 0.94);

            // 标记订单规模毒性到达率 (次/秒) 与闪崩连锁反应敏感度 (%)
            double toxicityIntensity = 15.0 + 25.0 * branchingRadius + (hash % 15);
