            spectrumWidth = Math.Clamp(spectrumWidth, 0.25, 0.65);

            double alphaZero = hurstH + 0.08 + (hash % 10) / 100.0;
            alphaZero = Math.Clamp(alphaZero, 0.50, 0.85);

            double memoryScore = Math.Abs(hurstH - 0.5) * 200.0 + 40.0;
            memoryScore = Math.Clamp(memoryScore, 35.0, 95.0);

            // 跨周期极值回撤对偶防御压降率 (%) 与反脆弱 Alpha (bps)
            double defenseGainPct = 20.0 + 35.0 * spectrumWidth + (double)(normW * 12m);
            defenseGainPct = Math.Clamp(defenseGainPct, 18.0, 52.0);

            double fractalAlpha = 15.0 + 22.0 * spectrumWidth + (hurstH > 0.55 ? 6.0 : 2.0);
            fractalAlpha = Math.Clamp(fractalAlpha, 14.0, 38.0);

            string badge;
            string advice;
            if (hurstH > 0.60 && spectrumWidth > 0.45)
