                advice = $"时序接近准高斯遍历布朗运动 (H={hurstH:F2} ≈ 0.5)，多重分形谱结构均匀稳定，维持常态全天候均衡配比，防范过度对冲摩擦成本。";
            }

            var item = new MultifractalHurstAssetItem
            {
                AssetCode = f.Code ?? string.Empty,
                AssetName = !string.IsNullOrEmpty(f.Name) ? f.Name : (f.Code ?? "资产"),
