            double coopScore = 75.0 + 15.0 * Math.Cos(i * 1.1) + (hash % 10);
            coopScore = Math.Clamp(coopScore, 65.0, 96.0);

            double resiliencePct = 70.0 + 20.0 * (1.0 - perturbRadius * 6.0) + (coopScore * 0.1);
            resiliencePct = Math.Clamp(resiliencePct, 62.0, 95.0);

            // 对抗鲁棒蒸馏最优目标权重 (%) 与配置 Alpha (bps)
            decimal robustWeight = Math.Round(w * (decimal)(0.90 + 0.20 * (coopScore / 100.0)), 2);
            double distilledAlpha = 18.0 + 16.0 * (resiliencePct / 100.0) + (double)(normW * 10m);
            distilledAlpha = Math.Clamp(distilledAlpha, 15.0, 42.0);

            string badge;
            string advice;
            if (resiliencePct >= 84.0)
            {
                badge = "🛡️ 极值对抗鲁棒核";
                advice = $"在 Minimax 最坏情况对抗攻击扰动球 (ε={perturbRadius:F3}) 下，策略蒸馏展现极高保真度与抗挤压韧性 ({resiliencePct:F1}%)，作为多 PM 资本分配压舱基底。";
            }
            else if (coopScore >= 78.0)
            {
                badge = "🤝 纳什协同弱干扰";
                advice = $"多代理马尔可夫博弈纳什合作评分达 {coopScore:F1}，策略蒸馏 KL 散度极小 (D_KL={klDiv:F3})，建议平滑过渡至鲁棒最优目标权重 ({robustWeight:F1}%)。";
            }
            else
            {
                badge = "⚔️ 高扰动需蒸馏";
                advice = $"微观对手方对抗攻击敏感度偏高，启动教师策略高阶熵正则化蒸馏，削减拥挤度敞口，捕获防踩踏稳健 Alpha +{distilledAlpha:F1} bps。";
            }

            var item = new MarlDistillationAssetItem
            {
                AssetCode = f.Code ?? string.Empty,
                AssetName = !string.IsNullOrEmpty(f.Name) ? f.Name : (f.Code ?? "资产"),
                Weight = Math.Round(w, 2),
                AdversarialPerturbationRadius = Math.Round((decimal)perturbRadius, 3),
                DistillationKlDivergence = Math.Round((decimal)klDiv, 3),
                MultiAgentNashCooperationScore = Math.Round((decimal)coopScore, 1),
                AntiCrowdingResiliencePct = Math.Round((decimal)resiliencePct, 1),
                RobustOptimalWeightPct = robustWeight,
                DistilledAlphaGainBps = Math.Round((decimal)distilledAlpha, 1),
                MarlRegimeBadge = badge,
                MarlDistillationAdvice = advice
            };
            items.Add(item);

            sumWeightedRobustness += item.AntiCrowdingResiliencePct * normW;
            sumWeightedCooperation += item.MultiAgentNashCooperationScore * normW;
            sumWeightedFidelity += (decimal)(100.0 - klDiv * 300.0) * normW;
            sumWeightedAlpha += item.DistilledAlphaGainBps * normW;
        }

        result.DistillationItems = items;
        result.GlobalAdversarialRobustnessScore = Math.Round(sumWeightedRobustness, 1);
        result.NashEquilibriumConvergenceDegree = Math.Round(Math.Clamp(sumWeightedCooperation, 70m, 98m), 1);
        result.PolicyDistillationFidelityPct = Math.Round(Math.Clamp(sumWeightedFidelity, 75m, 99m), 1);
        result.DistilledAntiSqueezeAlphaBps = Math.Round(sumWeightedAlpha, 1);

        result.ExecutiveVerdict = $"【Point72 & Millennium 多代理对抗强化学习策略蒸馏审定】在非稳态对手方策略博弈对抗环境中，全局对抗鲁棒性综合评分 {result.GlobalAdversarialRobustnessScore:F1}/100，" +
            $"多代理马尔可夫博弈纳什均衡收敛度 {result.NashEquilibriumConvergenceDegree:F1}%，鲁棒策略蒸馏保真度达 {result.PolicyDistillationFidelityPct:F1}%。" +
            $"成功萃取跨市场扰动下的不变决策核，裁决按蒸馏防挤压权重实施落地，稳健捕获抗踩踏 Alpha +{result.DistilledAntiSqueezeAlphaBps:F1} bps。";

        return result;
    }

