            }
            else if (q > 1.45m)
            {
                badge = "🌀 多重分形厚尾区";
                advice = $"非广延参数 q={q:F3}，Tsallis熵 S_q={sq:F3}，收益率呈现显著幂律长程记忆。利用多重分形尺度不变性捕获跨周期反相变收益。";
            }
