            });

            sumWeightedQ += q * w;
            sumWeightedDeltaAlpha += deltaAlpha * w;
            sumWeightedDefense += defensePct * w;
            sumWeightedAlpha += alphaBps * w;
        }

        result.TsallisItems = items;
