            // 3. 微秒级撮合延迟套利抢跑危险率 ξ_latency (%) (基于 5ms 延迟窗口)
            double hazardVal = Math.Clamp(12.0 + 38.0 * branchingVal * (1.0 - survivalVal / 100.0) + vol * 20.0, 8.0, 58.0);
            decimal hazardPct = Math.Round((decimal)hazardVal, 1);

            // 4. 最优跳级挂单半价差 delta_queue* (bps)
            double spreadVal = Math.Clamp(4.5 + 8.0 * branchingVal + 0.25 * hazardVal + vol * 15.0 + ((i * 7) % 5) * 0.4, 5.0, 28.0);
            decimal spreadBps = Math.Round((decimal)spreadVal, 2);

