                AssetCarbonBeta = carbonBeta,
                OrderlyTransitionImpactPct = orderlyPct,
                DisorderlyTransitionImpactPct = disorderlyPct,
                StrandedAssetExtremeVaRPct = strandedVaRPct,
                ClimateResilientTargetWeight = 0m,
                ClimateTransitionAlphaBps = alphaBps,
