                items[i].ClimateResilientTargetWeight = wNorm;
                allocatedSum += wNorm;
            }
        }

        result.ClimateItems = items;
        result.PortfolioWeightedCarbonBeta = Math.Round(sumWeightedBeta, 2);
        result.OrderlyScenarioPortfolioDrawdownPct = Math.Round(Math.Abs(sumWeightedOrderly), 1);
        result.DisorderlyStrandedWriteDownPct = 28.5m;
        result.TotalClimateTransitionAlphaBps = Math.Round(sumWeightedAlpha, 1);

        result.ExecutiveVerdict = $"【Aladdin & NBIM 气候审定】接入 NGFS 三大气候宏观转型三情景压力模型（组合加权碳贝塔 β_c = {result.PortfolioWeightedCarbonBeta:F2}）。" +
